insert into country_rules
  (country, pitch_angle, tone, main_value_prop, secondary_value_prop, target_titles, banned_claims, required_elements, cta, max_words)
values
('A', 'speed_to_fill', 'warm and professional', 'We fill open roles with a shortlist of vetted candidates, so hiring managers spend their time on interviews instead of sourcing.', 'One recruiter owns each role from brief to signed offer and reports progress every week.', array['Head of People','HR Director','Finance Director'], array['guaranteed hires','exact time-to-hire figures','fee or price figures','naming client companies'], array['say that timing depends on the role and the market','one clear call to action: a 20-minute call'], 'Would you have 20 minutes this week or next for a quick call?', 110),
('B', 'candidate_quality', 'direct and friendly', 'Every candidate on the shortlist is screened for skills and fit before the hiring manager sees them.', 'HR gets fewer, better interviews instead of an inbox full of CVs.', array['HR Director','Head of People','Finance Director'], array['guaranteed hires','promising the perfect candidate','fee or price figures','naming client companies'], array['lead with the quality of the candidates, not with speed','one clear call to action: a short call'], 'Do you have 20 minutes this week or next to walk through it together?', 110),
('C', 'hr_workload', 'polite and structured', 'We take sourcing and first-round screening off the HR team, so they can focus on onboarding and the people already there.', 'Clear weekly updates per role, so nobody has to chase the status.', array['HR Manager','HR Director','Head of People'], array['guaranteed hires','exact time-to-hire figures','fee or price figures','naming client companies'], array['mention that the process depends on the seniority of the role','one clear call to action: a short call'], 'Would you be available for a short 20-minute call this week or next?', 120),
('D', 'employer_brand', 'concise and factual', 'We present the company to candidates in a clear and consistent way, which helps when hiring in a competitive market.', 'One partner for several open roles instead of separate agencies.', array['Head of HR','Head of People','Finance Director'], array['superlatives such as the best or number one','salary or fee figures','guaranteed hires'], array['keep claims general, because hiring markets differ by country','one clear call to action: a short call'], 'Do you have 20 minutes this week or next for a short conversation?', 100)
